    "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 700 420\" width=\"100%\" height=\"100%\" style=\"background:#ffffff; border-radius:12px; font-family:system-ui, -apple-system, Cairo, Segoe UI, sans-serif;\">\n  <defs>\n    <linearGradient id=\"bgGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"100%\" stop-color=\"#f1f5f9\"/>\n    </linearGradient>\n    <marker id=\"arrowGreen\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#10b981\"/>\n    </marker>\n    <marker id=\"arrowBlue\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#0284c7\"/>\n    </marker>\n    <marker id=\"arrowRed\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#ef4444\"/>\n    </marker>\n  </defs>\n\n  <rect width=\"100%\" height=\"100%\" fill=\"url(#bgGrad1)\" rx=\"12\"/>\n  <rect x=\"15\" y=\"15\" width=\"670\" height=\"390\" rx=\"10\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n\n  <!-- Header -->\n  <rect x=\"30\" y=\"25\" width=\"640\" height=\"42\" rx=\"8\" fill=\"#0284c7\"/>\n  <text x=\"350\" y=\"52\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"800\" text-anchor=\"middle\">المسافة (Distance - d) مقابل الإزاحة (Displacement - x⃗)</text>\n\n  <!-- Point A (Start) -->\n  <circle cx=\"120\" cy=\"180\" r=\"14\" fill=\"#3b82f6\"/>\n  <circle cx=\"120\" cy=\"180\" r=\"6\" fill=\"#ffffff\"/>\n  <text x=\"120\" y=\"160\" fill=\"#1e293b\" font-size=\"14\" font-weight=\"800\" text-anchor=\"middle\">نقطة البداية (A)</text>\n\n  <!-- Point B (End) -->\n  <circle cx=\"560\" cy=\"180\" r=\"14\" fill=\"#ef4444\"/>\n  <circle cx=\"560\" cy=\"180\" r=\"6\" fill=\"#ffffff\"/>\n  <text x=\"560\" y=\"160\" fill=\"#1e293b\" font-size=\"14\" font-weight=\"800\" text-anchor=\"middle\">نقطة النهاية (B)</text>\n\n  <!-- Curved Path (Distance) -->\n  <path d=\"M 120 180 Q 220 70 340 120 T 560 180\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"4\" stroke-dasharray=\"8 6\"/>\n  <rect x=\"250\" y=\"85\" width=\"200\" height=\"32\" rx=\"6\" fill=\"#fffbeb\" stroke=\"#fde68a\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"106\" fill=\"#b45309\" font-size=\"13\" font-weight=\"700\" text-anchor=\"middle\">المسافة d = 500 m (مسار متعرج)</text>\n\n  <!-- Straight Arrow (Displacement) -->\n  <line x1=\"135\" y1=\"180\" x2=\"540\" y2=\"180\" stroke=\"#10b981\" stroke-width=\"5\" marker-end=\"url(#arrowGreen)\"/>\n  <rect x=\"240\" y=\"195\" width=\"220\" height=\"32\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#a7f3d0\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"216\" fill=\"#047857\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">الإزاحة x⃗ = 300 m شرقاً (خط مستقيم مباشر)</text>\n\n  <!-- Comparison Panels -->\n  <g transform=\"translate(35, 255)\">\n    <!-- Panel 1: In same direction -->\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"105\" rx=\"8\" fill=\"#ffffff\" stroke=\"#e2e8f0\" stroke-width=\"1.5\"/>\n    <text x=\"152\" y=\"24\" fill=\"#0369a1\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">الحالة 1: إزاحتان باتجاه واحد (جمع)</text>\n    <line x1=\"30\" y1=\"50\" x2=\"110\" y2=\"50\" stroke=\"#0284c7\" stroke-width=\"3\" marker-end=\"url(#arrowBlue)\"/>\n    <text x=\"70\" y=\"42\" fill=\"#0284c7\" font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">x₁ = 3 km</text>\n    <line x1=\"120\" y1=\"50\" x2=\"220\" y2=\"50\" stroke=\"#0284c7\" stroke-width=\"3\" marker-end=\"url(#arrowBlue)\"/>\n    <text x=\"170\" y=\"42\" fill=\"#0284c7\" font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">x₂ = 4 km</text>\n    <line x1=\"30\" y1=\"80\" x2=\"270\" y2=\"80\" stroke=\"#10b981\" stroke-width=\"4\" marker-end=\"url(#arrowGreen)\"/>\n    <text x=\"150\" y=\"98\" fill=\"#047857\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">المحصلة: x_net = 3 + 4 = 7 km شرقاً</text>\n  </g>\n\n  <g transform=\"translate(360, 255)\">\n    <!-- Panel 2: In opposite directions -->\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"105\" rx=\"8\" fill=\"#ffffff\" stroke=\"#e2e8f0\" stroke-width=\"1.5\"/>\n    <text x=\"152\" y=\"24\" fill=\"#b91c1c\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">الحالة 2: إزاحتان باتجاهين متعاكسين (طرح)</text>\n    <line x1=\"30\" y1=\"48\" x2=\"200\" y2=\"48\" stroke=\"#0284c7\" stroke-width=\"3\" marker-end=\"url(#arrowBlue)\"/>\n    <text x=\"115\" y=\"40\" fill=\"#0284c7\" font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">x₁ = 6 km شرقاً</text>\n    <line x1=\"200\" y1=\"68\" x2=\"140\" y2=\"68\" stroke=\"#ef4444\" stroke-width=\"3\" marker-end=\"url(#arrowRed)\"/>\n    <text x=\"170\" y=\"86\" fill=\"#ef4444\" font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">x₂ = 2 km غرباً</text>\n    <text x=\"152\" y=\"98\" fill=\"#b91c1c\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">المحصلة: x_net = 6 - 2 = 4 km شرقاً</text>\n  </g>\n\n  <!-- Footer Credit -->\n  <text x=\"660\" y=\"395\" fill=\"#64748b\" font-size=\"11\" font-weight=\"600\" text-anchor=\"end\">إعداد المهندس أسامة خليل هاشم</text>\n  <text x=\"40\" y=\"395\" fill=\"#0284c7\" font-size=\"11\" font-weight=\"700\">النظام التعليمي التفاعلي الشامل</text>\n</svg>"
