    "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 700 420\" width=\"100%\" height=\"100%\" style=\"background:#ffffff; border-radius:12px; font-family:system-ui, -apple-system, Cairo, Segoe UI, sans-serif;\">\n  <defs>\n    <linearGradient id=\"bgGrad13\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"100%\" stop-color=\"#f1f5f9\"/>\n    </linearGradient>\n  </defs>\n\n  <rect width=\"100%\" height=\"100%\" fill=\"url(#bgGrad13)\" rx=\"12\"/>\n  <rect x=\"15\" y=\"15\" width=\"670\" height=\"390\" rx=\"10\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n\n  <!-- Header -->\n  <rect x=\"30\" y=\"25\" width=\"640\" height=\"42\" rx=\"8\" fill=\"#047857\"/>\n  <text x=\"350\" y=\"52\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"800\" text-anchor=\"middle\">الألياف البصرية (Fiber Optics) وتحلل الضوء بالمنشور (Prism)</text>\n\n  <!-- Left: Fiber Optics Total Internal Reflection -->\n  <g transform=\"translate(35, 75)\">\n    <rect width=\"315\" height=\"280\" rx=\"8\" fill=\"#ffffff\" stroke=\"#a7f3d0\" stroke-width=\"1.5\"/>\n    <rect width=\"315\" height=\"35\" rx=\"8\" fill=\"#d1fae5\"/>\n    <text x=\"157\" y=\"23\" fill=\"#065f46\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">1. الانعكاس الكلي الداخلي (الألياف)</text>\n\n    <!-- Fiber Core Tube -->\n    <path d=\"M 20 80 Q 150 60 295 100 L 295 150 Q 150 110 20 130 Z\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"157\" y=\"165\" fill=\"#0369a1\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">قلب الليف البصري (زجاج نقي عالي الكثافة)</text>\n\n    <!-- Bouncing Light Ray -->\n    <path d=\"M 20 105 L 85 70 L 165 125 L 240 85 L 295 125\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n    <circle cx=\"85\" cy=\"70\" r=\"4\" fill=\"#f59e0b\"/>\n    <circle cx=\"165\" cy=\"125\" r=\"4\" fill=\"#f59e0b\"/>\n    <circle cx=\"240\" cy=\"85\" r=\"4\" fill=\"#f59e0b\"/>\n\n    <rect x=\"15\" y=\"185\" width=\"285\" height=\"75\" rx=\"6\" fill=\"#f0fdf4\" stroke=\"#86efac\"/>\n    <text x=\"142\" y=\"205\" fill=\"#166534\" font-size=\"11\" font-weight=\"800\" text-anchor=\"middle\">شرط الانعكاس الكلي الداخلي:</text>\n    <text x=\"142\" y=\"223\" fill=\"#15803d\" font-size=\"10\" text-anchor=\"middle\">1. من وسط أكبر كثافة (زجاج) لأقل كثافة (هواء)</text>\n    <text x=\"142\" y=\"243\" fill=\"#047857\" font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">2. زاوية السقوط أكبر من الزاوية الحرجة (θ &gt; θ_c)</text>\n  </g>\n\n  <!-- Right: Glass Prism Dispersion -->\n  <g transform=\"translate(370, 75)\">\n    <rect width=\"295\" height=\"280\" rx=\"8\" fill=\"#ffffff\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n    <rect width=\"295\" height=\"35\" rx=\"8\" fill=\"#f1f5f9\"/>\n    <text x=\"147\" y=\"23\" fill=\"#1e293b\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">2. تحلل الضوء الأبيض بالمنشور</text>\n\n    <!-- Glass Prism Triangle -->\n    <polygon points=\"120,50 40,170 200,170\" fill=\"#f8fafc\" stroke=\"#64748b\" stroke-width=\"2\"/>\n    <text x=\"120\" y=\"145\" fill=\"#64748b\" font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">منشور زجاجي</text>\n\n    <!-- White Light Beam In -->\n    <line x1=\"0\" y1=\"125\" x2=\"65\" y2=\"125\" stroke=\"#f59e0b\" stroke-width=\"4\"/>\n    <text x=\"30\" y=\"115\" fill=\"#b45309\" font-size=\"10\" font-weight=\"800\">ضوء أبيض</text>\n\n    <!-- 7 Rainbow Spectrum Colors Out -->\n    <!-- Red (least deviated) -->\n    <line x1=\"160\" y1=\"125\" x2=\"280\" y2=\"80\" stroke=\"#ef4444\" stroke-width=\"2.5\"/>\n    <text x=\"285\" y=\"83\" fill=\"#ef4444\" font-size=\"9\" font-weight=\"800\">أحمر (الأقل انحرافاً)</text>\n    <!-- Orange -->\n    <line x1=\"160\" y1=\"125\" x2=\"275\" y2=\"95\" stroke=\"#f97316\" stroke-width=\"2\"/>\n    <!-- Yellow -->\n    <line x1=\"160\" y1=\"125\" x2=\"270\" y2=\"110\" stroke=\"#eab308\" stroke-width=\"2\"/>\n    <!-- Green -->\n    <line x1=\"160\" y1=\"125\" x2=\"265\" y2=\"125\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n    <!-- Blue -->\n    <line x1=\"160\" y1=\"125\" x2=\"260\" y2=\"140\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <!-- Indigo -->\n    <line x1=\"160\" y1=\"125\" x2=\"255\" y2=\"155\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n    <!-- Violet (most deviated) -->\n    <line x1=\"160\" y1=\"125\" x2=\"250\" y2=\"170\" stroke=\"#a855f7\" stroke-width=\"2.5\"/>\n    <text x=\"255\" y=\"185\" fill=\"#9333ea\" font-size=\"9\" font-weight=\"800\">بنفسجي (الأكثر انحرافاً)</text>\n\n    <rect x=\"15\" y=\"200\" width=\"265\" height=\"60\" rx=\"6\" fill=\"#fdf4ff\" stroke=\"#f0abfc\"/>\n    <text x=\"132\" y=\"222\" fill=\"#86198f\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">تفسير تكون قوس قزح في السماء:</text>\n    <text x=\"132\" y=\"242\" fill=\"#701a75\" font-size=\"9.5\" text-anchor=\"middle\">قطرات المطر المعلقة تعمل كمنشورات دقيقة</text>\n  </g>\n\n  <!-- Footer Credit -->\n  <text x=\"660\" y=\"395\" fill=\"#64748b\" font-size=\"11\" font-weight=\"600\" text-anchor=\"end\">إعداد المهندس أسامة خليل هاشم</text>\n  <text x=\"40\" y=\"395\" fill=\"#047857\" font-size=\"11\" font-weight=\"700\">النظام التعليمي التفاعلي الشامل</text>\n</svg>"
