// Helper function to look up diagram for a lesson or topic
window.getPhysicsDiagram = function(lessonId) {
  if (!window.PHYSICS_DIAGRAMS) return null;
  const numId = Number(lessonId);
  return window.PHYSICS_DIAGRAMS.find(d => d.lessonId === numId) || null;
};
